-- lib_811_dig_core_precheck.sql: SELECT only. Expect already_there = 0 (first run), to_replace_found = 8, and rows = max_ord + 1.
select (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and chunk->>'id' in ('dig-ca-overview-1', 'dig-ca-damage-1', 'dig-ca-penalties-1', 'dig-az-overview-1', 'dig-az-tickets-1', 'dig-az-marks-1', 'dig-az-damage-1', 'dig-nv-overview-1', 'dig-nv-tickets-1', 'dig-nv-marks-1', 'dig-nv-damage-1', 'dig-tx-overview-1', 'dig-tx-tickets-1', 'dig-tx-marks-1', 'dig-tx-damage-1', 'dig-fl-overview-1', 'dig-fl-tickets-1', 'dig-fl-marks-1', 'dig-fl-damage-1', 'dig-wa-overview-1', 'dig-wa-tickets-1', 'dig-wa-marks-1', 'dig-wa-damage-1', 'dig-or-overview-1', 'dig-or-tickets-1', 'dig-or-marks-1', 'dig-or-damage-1', 'dig-co-overview-1', 'dig-co-tickets-1', 'dig-co-marks-1', 'dig-co-damage-1')) as already_there,
       (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and chunk->>'id' in ('dig-ca', 'dig-az', 'dig-nv', 'dig-tx', 'dig-fl', 'dig-wa', 'dig-or', 'dig-co')) as to_replace_found,
       (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as rows,
       (select max(ord) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') as max_ord;
